const raw = $input.first().json;
const body = (raw && raw.body && typeof raw.body === 'object' && Object.keys(raw.body).length > 0) ? raw.body : raw;

// 1. Duelo activo o paciente fallecido -> Supresión incondicional
if (body.is_bereaved === true || body.is_deceased === true) {
  return [{
    json: {
      action: 'SUPPRESS_BEREAVEMENT',
      reason: 'Paciente fallecido o tutor en protocolo de duelo. Recordatorios comerciales y de cobro suprimidos.',
      is_eligible: false,
      client_id: body.client_id || body.owner_id,
      client_phone: body.client_phone || body.phone_e164,
      evaluated_at: new Date().toISOString()
    }
  }];
}

// 2. Cuidador revocado -> Supresión estricta
if (body.caregiver_revoked === true) {
  return [{
    json: {
      action: 'SUPPRESS_CAREGIVER_REVOKED',
      reason: 'El cuidador destinatario ha sido revocado. Entrega financiera cancelada.',
      is_eligible: false,
      client_id: body.client_id || body.owner_id,
      client_phone: body.client_phone || body.phone_e164,
      evaluated_at: new Date().toISOString()
    }
  }];
}

// 3. Disputa abierta -> Supresión de recordatorios
if (body.has_open_dispute === true || body.dispute_active === true) {
  return [{
    json: {
      action: 'SUPPRESS_DISPUTE_ACTIVE',
      reason: 'Existe una disputa o aclaración financiera abierta. Recordatorios automáticos congelados.',
      is_eligible: false,
      client_id: body.client_id || body.owner_id,
      client_phone: body.client_phone || body.phone_e164,
      evaluated_at: new Date().toISOString()
    }
  }];
}

// 4. Reporte de transferencia con captura -> NUNCA auto-paid; requiere revisión humana
if (body.event_type === 'TRANSFER_REPORTED' || body.verification_status === 'PENDING_VERIFICATION') {
  return [{
    json: {
      action: 'ALERT_FINANCE_VERIFICATION_REQUIRED',
      reason: 'Comprobante de transferencia recibido. Requiere conciliación con extracto bancario.',
      is_eligible: false,
      requires_finance_review: true,
      collection_id: body.collection_id || body.report_id,
      payment_method: body.payment_method || body.bank_name,
      amount_cop: body.amount_cop || body.amount,
      amount_formatted: '$' + Number(body.amount_cop || body.amount || 0).toLocaleString('es-CO') + ' COP',
      client_name: body.client_name,
      client_phone: body.client_phone || body.phone_e164,
      evaluated_at: new Date().toISOString()
    }
  }];
}

// 5. Presupuesto en borrador o no aprobado -> Bloqueado para envío
if (body.event_type === 'QUOTE_PENDING' && body.is_approved !== true) {
  return [{
    json: {
      action: 'REJECT_UNAPPROVED_QUOTE',
      reason: 'El presupuesto está en DRAFT o pendiente de aprobación. No se puede despachar.',
      is_eligible: false,
      quote_id: body.quote_id,
      evaluated_at: new Date().toISOString()
    }
  }];
}

// 6. Solicitud de reembolso sin aprobación humana -> Bloqueado
if (body.event_type === 'REFUND_REQUESTED' && body.is_approved !== true) {
  return [{
    json: {
      action: 'ALERT_REFUND_APPROVAL_REQUIRED',
      reason: 'Solicitud de reembolso requiere aprobación formal de Dirección Médica / Finanzas.',
      is_eligible: false,
      refund_id: body.refund_id,
      evaluated_at: new Date().toISOString()
    }
  }];
}

// 7. Flujo Nominal Elegible (Pago Verificado, Presupuesto Aprobado, Solicitud Emitida)
const amountFmt = '$' + Number(body.amount_cop || body.amount || 0).toLocaleString('es-CO') + ' COP';
return [{
  json: {
    action: 'DISPATCH_FINANCIAL_NOTIFICATION',
    is_eligible: true,
    event_type: body.event_type || 'PAYMENT_CONFIRMED',
    collection_id: body.collection_id || body.payment_request_id,
    receipt_number: body.receipt_number || body.invoice_number || 'REC-AUTO',
    payment_method: body.payment_method || 'DIGITAL',
    amount_cop: body.amount_cop || body.amount || 0,
    amount_formatted: amountFmt,
    client_name: body.client_name || 'Tutor Vet Life',
    client_phone: body.client_phone || body.phone_e164 || '+573000000000',
    target_phone: body.client_phone || body.phone_e164 || '+573000000000',
    template_name: 'vet_life_payment_receipt_v1',
    send_enabled: false,
    evaluated_at: new Date().toISOString()
  }
}];
